sys_security_acl.script:
answer = false;

// 1. Admins, Placement Officers, and HR always get access
if (gs.hasRole('x_snc_college_pl_0.placement_officer') || gs.hasRole('x_snc_college_pl_0.placement_admin') || gs.hasRole('admin') || gs.hasRole('x_snc_college_pl_0.student_user')) {
    answer = true;
} else {
    // 2. Query Student table matching the logged-in user
    var stu = new GlideRecord('x_snc_college_pl_0_student');
    if (stu.get('user', gs.getUserID())) {

        var studentCgpa = parseFloat(stu.getValue('cgpa'));
        var requiredCgpa = parseFloat(current.getValue('minimum_cgpa'));
        var eligibleBranches = current.getValue('eligible_branches') || '';
        var studentBranch = stu.getValue('branch');

        // 3. Compare CGPA and Branch
        if (!isNaN(studentCgpa) && !isNaN(requiredCgpa)) {
            if (studentCgpa >= requiredCgpa && eligibleBranches.indexOf(studentBranch) !== -1) {
                answer = true;
            }
        }
    }
}
